import fetcher

# Mock client to simulate the behavior of a requests.Session-like object
class MockClient:
    def __init__(self):
        self.last_url = None
        self.last_timeout = None
        self.last_kwargs = None
        self.exception = None

    def get(self, url, timeout=None, **kwargs):
        self.last_url = url
        self.last_timeout = timeout
        self.last_kwargs = kwargs
        if self.exception:
            raise self.exception
        return MockResponse()

class MockResponse:
    def __init__(self):
        pass

def test_timeout_set():
    client = MockClient()
    try:
        fetcher.fetch(client, "https://example.com")
    except Exception:
        pass
    assert client.last_timeout == 30, "Timeout should be set to 30"

def test_args_preserved():
    client = MockClient()
    try:
        fetcher.fetch(client, "https://example.com")
    except Exception:
        pass
    assert client.last_kwargs == {}, "No additional kwargs should be added"

def test_exception_propagation():
    client = MockClient()
    client.exception = Exception("Test exception")
    try:
        fetcher.fetch(client, "https://example.com")
    except Exception as e:
